WITH sales_daily AS (SELECT cs_call_center_sk, cs_sold_date_sk AS date_sk, SUM(cs_net_paid_inc_tax) AS daily_sales, SUM(cs_net_profit) AS daily_profit FROM catalog_sales GROUP BY cs_call_center_sk, cs_sold_date_sk), returns_daily AS (SELECT cr_call_center_sk, cr_returned_date_sk AS date_sk, SUM(cr_return_amount) AS daily_returns, SUM(cr_net_loss) AS daily_loss FROM catalog_returns GROUP BY cr_call_center_sk, cr_returned_date_sk), combined AS (SELECT COALESCE(s.cs_call_center_sk, r.cr_call_center_sk) AS call_center_sk, COALESCE(s.date_sk, r.date_sk) AS date_sk, COALESCE(s.daily_sales,0) AS daily_sales, COALESCE(s.daily_profit,0) AS daily_profit, COALESCE(r.daily_returns,0) AS daily_returns, COALESCE(r.daily_loss,0) AS daily_loss FROM sales_daily s FULL OUTER JOIN returns_daily r ON s.cs_call_center_sk = r.cr_call_center_sk AND s.date_sk = r.date_sk) SELECT cc.cc_name, c.date_sk, c.daily_sales, c.daily_returns, c.daily_sales - c.daily_returns AS net_daily_sales, LAG(c.daily_sales - c.daily_returns) OVER (PARTITION BY cc.cc_name ORDER BY c.date_sk) AS prev_day_net_sales, c.daily_sales - LAG(c.daily_sales) OVER (PARTITION BY cc.cc_name ORDER BY c.date_sk) AS sales_change_vs_prev, AVG(c.daily_sales - c.daily_returns) OVER (PARTITION BY cc.cc_name ORDER BY c.date_sk ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7d, CASE WHEN EXISTS (SELECT 1 FROM catalog_returns cr JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk WHERE cr.cr_call_center_sk = c.call_center_sk AND cr.cr_returned_date_sk = c.date_sk AND r.r_reason_desc = 'Damaged') THEN 'Damaged Return' ELSE 'No Damaged Return' END AS damaged_return_flag FROM combined c JOIN call_center cc ON c.call_center_sk = cc.cc_call_center_sk WHERE c.date_sk IS NOT NULL ORDER BY cc.cc_name, c.date_sk LIMIT 200
